import re


class NotFound(Exception):
    pass


class MethodNotAllowed(Exception):
    pass


class Router:
    def __init__(self):
        self.routes = []  # list of (method, pattern_segments, handler, is_static)

    def add(self, method: str, pattern: str, handler):
        segments = self._split(pattern)
        is_static = all(not self._is_param(seg) for seg in segments)
        self.routes.append((method, segments, handler, is_static))

    def dispatch(self, method: str, path: str) -> tuple:
        path_segments = self._split(path)
        matched_methods = set()
        # Prefer static routes
        for route in self.routes:
            r_method, r_segments, handler, is_static = route
            if len(r_segments) != len(path_segments):
                continue
            params = self._match(r_segments, path_segments)
            if params is None:
                continue
            matched_methods.add(r_method)
            if r_method == method:
                if is_static:
                    return (handler, params)
        # If no static match, check parameter routes
        for route in self.routes:
            r_method, r_segments, handler, is_static = route
            if len(r_segments) != len(path_segments):
                continue
            params = self._match(r_segments, path_segments)
            if params is None:
                continue
            if r_method == method:
                return (handler, params)
        if matched_methods:
            raise MethodNotAllowed(f"Method {method} not allowed for path {path}")
        raise NotFound(f"No route found for path {path}")

    @staticmethod
    def _split(path: str) -> list:
        # Remove leading/trailing slashes, split by '/'
        path = path.strip('/')
        if not path:
            return []
        return path.split('/')

    @staticmethod
    def _is_param(segment: str) -> bool:
        return segment.startswith('{') and segment.endswith('}')

    @staticmethod
    def _match(pattern_segments: list, path_segments: list) -> dict:
        params = {}
        for p_seg, path_seg in zip(pattern_segments, path_segments):
            if Router._is_param(p_seg):
                name = p_seg[1:-1]
                if not path_seg:
                    return None
                params[name] = path_seg
            else:
                if p_seg != path_seg:
                    return None
        return params
